parameters.jsCode:
// Validate input
const input = $input.item.json;

if (!input.applicationNumber || !input.spreadsheetId) {
  throw new Error('applicationNumber and spreadsheetId are required');
}

return [{ json: input }];

// Parse pricing data from Google Sheet
const rows = $input.item.json.values || [];

if (rows.length < 2) {
  throw new Error('No pricing data found in sheet');
}

// Skip header row
const headers = rows[0];
const dataRows = rows.slice(1);

// Parse pricing for each manufacturer
const bomWithPricing = {
  ruckus: [],
  extreme: [],
  ubiquiti: []
};

let ruckusTotal = 0;
let extremeTotal = 0;
let ubiquitiTotal = 0;

dataRows.forEach(row => {
  if (!row[0]) return; // Skip empty rows

  const item = {
    category: row[0],
    quantity: parseInt(row[1]) || 0,
    specifications: row[2],
    requiredFeatures: row[3] ? row[3].split(',').map(f => f.trim()) : []
  };

  // Ruckus
  if (row[4]) { // Has Ruckus part number
    const unitPrice = parseFloat(row[5]) || 0;
    const total = item.quantity * unitPrice;
    ruckusTotal += total;

    bomWithPricing.ruckus.push({
      ...item,
      partNumber: row[4],
      unitPrice: unitPrice,
      total: total
    });
  }

  // Extreme
  if (row[7]) { // Has Extreme part number
    const unitPrice = parseFloat(row[8]) || 0;
    const total = item.quantity * unitPrice;
    extremeTotal += total;

    bomWithPricing.extreme.push({
      ...item,
      partNumber: row[7],
      unitPrice: unitPrice,
      total: total
    });
  }

  // Ubiquiti
  if (row[10]) { // Has Ubiquiti part number
    const unitPrice = parseFloat(row[11]) || 0;
    const total = item.quantity * unitPrice;
    ubiquitiTotal += total;

    bomWithPricing.ubiquiti.push({
      ...item,
      partNumber: row[10],
      unitPrice: unitPrice,
      total: total
    });
  }
});

return [{
  json: {
    applicationNumber: $input.item.json.applicationNumber,
    spreadsheetId: $input.item.json.spreadsheetId,
    bomWithPricing: bomWithPricing,
    totals: {
      ruckus: ruckusTotal,
      extreme: extremeTotal,
      ubiquiti: ubiquitiTotal
    },
    pricingComplete: true
  }
}];

// Format BOM data for proposal generation
const data = $input.item.json;

return [{
  json: {
    applicationNumber: data.applicationNumber,
    bomData: {
      primary: data.bomWithPricing.ruckus,
      alternative_extreme: data.bomWithPricing.extreme,
      alternative_ubiquiti: data.bomWithPricing.ubiquiti,
      totals: data.totals
    },
    readyForProposal: true,
    pricingSource: 'manual',
    spreadsheetId: data.spreadsheetId
  }
}];

